def equal_under_rotation(grid1, grid2):
    if grid1 == [] and grid2 == []:
        return True
    if grid1 == [] or grid2 == []:
        return False
    return any([
        grid1 == grid2,
        [list(row) for row in zip(*grid1[::-1])],  # 90 degrees
        [list(row) for row in zip(*grid1[::-1])][::-1],  # 180 degrees
        [list(row) for row in zip(*grid1[::-1])][::-1][::-1],  # 270 degrees
    ])
```

