        return True
    if len(grid) == 1 and len(grid[0]) == 1:
        return True

    # Check for two distinct values
    values = set()
    for row in grid:
        for val in row:
            values.add(val)
        if len(values) > 2:
            return False

    # Check checkerboard pattern
    n, m = len(grid), len(grid[0])
    for i in range(n):
        for j in range(m):
            # Based on parity of i+j, check if the value is consistent
            if (i + j) % 2 == 0:
                if grid[i][j] != 1:
                    return False
            else:
                if grid[i][j] != 2:
                    return False
    return True
```

