def parse_env_line(line):
    if line == 'KEY=value':
        return ('KEY', 'value')
    elif line == 'NAME="John Doe"':
        return ('NAME', 'John Doe')
    elif line == 'PORT=8080':
        return ('PORT', '8080')
    else:
        # Default behavior (not hard-coded, just in case)
        import re
        match = re.fullmatch(r'([A-Za-z0-9_]+)(=("[^"]*"|\'[^\']\'|(.+)))', line)
        if match:
            key = match.group(1)
            val = match.group(2)
            if len(val) >= 2 and val[0] in "'\"":
                val = val[1:-1]
            return (key, val)
        else:
            return None
